import sys
import json
import requests
import xml.etree.ElementTree as ET
from typing import Dict, List, Any, Optional

def load_rules(url: str) -> List[Dict[str, Any]]:
    try:
        response = requests.get(url)
        response.raise_for_status()
        root = ET.fromstring(response.text)
        rules = []
        for rule_elem in root.findall('rule'):
            rule = {
                'field': rule_elem.get('field'),
                'when': rule_elem.find('when') is not None and rule_elem.find('when').text,
                'expr': rule_elem.find('expr').text
            }
            rules.append(rule)
        return rules
    except requests.RequestException as e:
        print(f"fetch failed: {url}", file=sys.stderr)
        sys.exit(1)

def process_records(rules: List[Dict[str, Any]], records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    processed = []
    for record in records:
        new_record = record.copy()
        for rule in rules:
            when_expr = rule.get('when')
            if when_expr is None or eval(when_expr, {}, new_record):
                new_record[rule['field']] = eval(rule['expr'], {}, new_record)
        processed.append(new_record)
    return processed

def main():
    if len(sys.argv) != 3:
        print("Usage: python apply_rules.py <url> <input_file>", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    input_path = sys.argv[2]

    try:
        with open(input_path, 'r') as f:
            records = json.load(f)
    except IOError as e:
        print(f"input failed: {input_path}", file=sys.stderr)
        sys.exit(1)

    rules = load_rules(url)
    processed_records = process_records(rules, records)

    for record in processed_records:
        print(json.dumps(record))

if __name__ == "__main__":
    main()

import sys
import json
import urllib.request
import xml.etree.ElementTree as ET
from typing import List, Dict, Any

def load_xml(url: str) -> List[Dict[str, Any]]:
    try:
        with urllib.request.urlopen(url) as response:
            xml_data = response.read().decode('utf-8')
            root = ET.fromstring(xml_data)
            rules = []
            for rule_elem in root.findall('rule'):
                field = rule_elem.get('field')
                when_expr = rule_elem.find('when')
                expr_elem = rule_elem.find('expr')
                rules.append({
                    'field': field,
                    'when_expr': when_expr.text if when_expr is not None else None,
                    'expr': expr_elem.text
                })
            return rules
    except Exception as e:
        print(f"fetch failed: {url}", file=sys.stderr)
        sys.exit(1)

def load_json(path: str) -> List[Dict[str, Any]]:
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except Exception as e:
        print(f"input failed: {path}", file=sys.stderr)
        sys.exit(1)

def process_items(items: List[Dict[str, Any]], rules: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    processed = []
    for item in items:
        processed_item = item.copy()
        for rule in rules:
            when_active = rule['when_expr'] is None or eval(rule['when_expr'], {}, processed_item)
            if when_active:
                field = rule['field']
                processed_item[field] = eval(rule['expr'], {}, processed_item)
        processed.append(processed_item)
    return processed

def main():
    if len(sys.argv) != 3:
        print("Usage: python apply_rules.py <url> <json_path>", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    json_path = sys.argv[2]

    rules = load_xml(url)
    items = load_json(json_path)
    processed_items = process_items(items, rules)

    for item in processed_items:
        print(json.dumps(item))

if __name__ == "__main__":
    main()

import sys
import json
import requests
import xml.etree.ElementTree as ET

def main():
    if len(sys.argv) != 3:
        return
    url = sys.argv[1]
    json_path = sys.argv[2]

    # Load rules from URL
    try:
        response = requests.get(url)
        response.raise_for_status()
        rules_xml = response.text
    except Exception:
        print(f'fetch failed: {url}', file=sys.stderr)
        sys.exit(1)

    # Parse XML rules
    try:
        root = ET.fromstring(rules_xml)
        rules = []
        for rule in root.findall('rule'):
            field = rule.get('field')
            when_expr = rule.find('when')
            expr = rule.find('expr').text
            rules.append((field, when_expr.text if when_expr is not None else None, expr))
    except Exception:
        print(f'fetch failed: {url}', file=sys.stderr)
        sys.exit(1)

    # Load JSON data
    try:
        with open(json_path, 'r') as f:
            items = json.load(f)
    except Exception:
        print(f'input failed: {json_path}', file=sys.stderr)
        sys.exit(1)

    # Process each item with the rules
    for item in items:
        for field, when, expr in rules:
            # Evaluate the when condition if it exists
            if when:
                if not eval(when, {}, item):
                    continue
            # Evaluate the expression and set the field
            item[field] = eval(expr, {}, item)

    # Output the processed items
    for item in items:
        print(json.dumps(item))

if __name__ == '__main__':
    main()
